function Invoke-GitChecked {
  & git @args
  if ($LASTEXITCODE -ne 0) { throw "git $($args -join ' ') failed" }
}

function Test-GitDirty {
  $dirty = & git status --porcelain
  if ($LASTEXITCODE -ne 0) { throw "git status failed" }
  if ($null -eq $dirty) { return $false }
  return @($dirty).Count -gt 0
}

function Test-GitRef {
  param([string]$Ref)

  & git show-ref --verify --quiet $Ref *> $null
  if ($LASTEXITCODE -eq 0) { return $true }
  if ($LASTEXITCODE -eq 1) { return $false }
  throw "git show-ref failed"
}

function Read-Answer {
  param([string]$Question, [string]$Default)

  $reply = Read-Host -Prompt "$Question [$Default]"
  if ([string]::IsNullOrWhiteSpace($reply)) { return $Default }
  return $reply.Trim()
}

function Confirm-Step {
  param([string]$Question, [string]$Default)

  while ($true) {
    $reply = Read-Answer -Question $Question -Default $Default
    if ($reply -match '^[Yy]') { return $true }
    if ($reply -match '^[Nn]') { return $false }
    Write-Host "Please answer y or n."
  }
}

$script:GitSyncStashed = $false

function Restore-GitStash {
  if (-not $script:GitSyncStashed) { return }
  $script:GitSyncStashed = $false
  & git stash pop
  if ($LASTEXITCODE -ne 0) {
    throw "Stash restore stopped. Resolve conflicts before continuing; the stash was kept as stash@{0}."
  }
  Write-Host "Restored your uncommitted changes."
}

function Stop-OnRebaseConflict {
  Write-Host "Rebase stopped on conflicts."
  if (Confirm-Step -Question "Abort the rebase and put everything back? (n leaves it for you to resolve)" -Default "y") {
    & git rebase --abort
    Restore-GitStash
    throw "Rebase aborted; nothing was pushed or reinstalled."
  }
  if ($script:GitSyncStashed) { Write-Host "Your uncommitted changes are in stash@{0}; pop them afterwards." }
  throw "Resolve the conflicts, run git rebase --continue, then run this command again."
}

function Update-GitMain {
  param([string]$RemoteName, [string]$MainBranch)

  Invoke-GitChecked switch $MainBranch
  & git merge --ff-only "$RemoteName/$MainBranch"
  if ($LASTEXITCODE -ne 0) {
    throw "$MainBranch cannot be fast-forwarded from $RemoteName/$MainBranch. Resolve $MainBranch manually, then retry."
  }
}

function Invoke-EspansrReinstall {
  if (Get-Command espansr -ErrorAction SilentlyContinue) {
    Write-Host "Reinstalling espansr with 'espansr refresh'..."
    & espansr refresh
  } elseif (Test-Path -LiteralPath ".\install.ps1") {
    Write-Host "espansr is not on PATH; running .\install.ps1..."
    & ".\install.ps1"
  } else {
    throw "espansr is not installed and there is no install.ps1 here; reinstall skipped."
  }
  if ($LASTEXITCODE -ne 0) { throw "espansr reinstall failed (exit $LASTEXITCODE)." }
}

function Invoke-GitSyncReinstall {
  $remoteName = "origin"
  $mainBranch = "main"
  $head = & git symbolic-ref --quiet --short "refs/remotes/$remoteName/HEAD" 2>$null
  if ($LASTEXITCODE -eq 0 -and -not [string]::IsNullOrWhiteSpace($head)) {
    $mainBranch = $head.Trim() -replace "^$remoteName/", ""
  }

  $branch = (& git branch --show-current)
  if ($LASTEXITCODE -ne 0 -or [string]::IsNullOrWhiteSpace($branch)) { throw "Not on a branch." }
  $branch = $branch.Trim()

  Write-Host "Fetching $remoteName..."
  & git fetch --prune $remoteName
  if ($LASTEXITCODE -ne 0) {
    Write-Host "Could not fetch $remoteName (offline?)."
    if (Confirm-Step -Question "Skip the update and only reinstall espansr?" -Default "n") {
      Invoke-EspansrReinstall
      return
    }
    throw "Update cancelled."
  }
  if (-not (Test-GitRef -Ref "refs/remotes/$remoteName/$mainBranch")) {
    throw "Remote $remoteName/$mainBranch was not found."
  }

  if (Test-GitDirty) {
    & git status --short
    $choice = Read-Answer -Question "Uncommitted changes: [c]ommit them, [s]tash and restore them after the update, or [a]bort?" -Default "s"
    if ($choice -match '^[Cc]') {
      if ($branch -eq $mainBranch) {
        $workBranch = "work/sync-" + (Get-Date -Format "yyyyMMdd-HHmmss")
        Write-Host "Local changes are on main; moving them to $workBranch before updating main."
        Invoke-GitChecked switch -c $workBranch
        $branch = $workBranch
      }
      Invoke-GitChecked add -A
      $message = Read-Answer -Question "Commit message:" -Default "chore: sync local changes"
      Invoke-GitChecked commit -m $message
    } elseif ($choice -match '^[Aa]') {
      throw "Aborted; nothing changed."
    } else {
      Invoke-GitChecked stash push -u -m "git-sync"
      $script:GitSyncStashed = $true
    }
  }

  if ($branch -eq $mainBranch) {
    Write-Host "Updating $mainBranch from $remoteName/$mainBranch..."
    & git merge --ff-only "$remoteName/$mainBranch"
    if ($LASTEXITCODE -ne 0) {
      Write-Host "$mainBranch has local commits; rebasing them onto $remoteName/$mainBranch."
      & git rebase "$remoteName/$mainBranch"
      if ($LASTEXITCODE -ne 0) { Stop-OnRebaseConflict }
    }
    $ahead = [int](& git rev-list --count "$remoteName/$mainBranch..HEAD")
    if ($ahead -gt 0 -and (Confirm-Step -Question "Push $ahead local commit(s) to $remoteName/${mainBranch}?" -Default "y")) {
      Invoke-GitChecked push $remoteName $mainBranch
    }
  } else {
    $hasRemoteBranch = Test-GitRef -Ref "refs/remotes/$remoteName/$branch"
    if ($hasRemoteBranch) {
      Write-Host "Updating $branch from $remoteName/$branch..."
      & git rebase "$remoteName/$branch"
      if ($LASTEXITCODE -ne 0) { Stop-OnRebaseConflict }
    }
    Write-Host "Updating $mainBranch from $remoteName/$mainBranch..."
    try {
      Update-GitMain -RemoteName $remoteName -MainBranch $mainBranch
    } catch {
      & git switch $branch *> $null
      Restore-GitStash
      throw
    }
    Invoke-GitChecked switch $branch
    Write-Host "Rebasing $branch onto $mainBranch..."
    & git rebase $mainBranch
    if ($LASTEXITCODE -ne 0) { Stop-OnRebaseConflict }

    if (Confirm-Step -Question "Merge $branch into $mainBranch and push ${mainBranch}?" -Default "n") {
      Invoke-GitChecked switch $mainBranch
      Invoke-GitChecked merge --no-ff $branch -m "Merge $branch"
      Invoke-GitChecked push $remoteName $mainBranch
      if (Confirm-Step -Question "Delete $branch locally and on ${remoteName}?" -Default "n") {
        Invoke-GitChecked branch -d $branch
        if ($hasRemoteBranch) { Invoke-GitChecked push $remoteName --delete $branch }
      }
      $branch = $mainBranch
    } elseif ($hasRemoteBranch) {
      if (Confirm-Step -Question "Push $branch to $remoteName (force-with-lease, since it was rebased)?" -Default "y") {
        Invoke-GitChecked push --force-with-lease $remoteName $branch
      }
    } elseif (Confirm-Step -Question "Publish $branch to ${remoteName}?" -Default "y") {
      Invoke-GitChecked push --set-upstream $remoteName $branch
    }
  }

  Restore-GitStash

  if (Confirm-Step -Question "Reinstall espansr now?" -Default "y") {
    Invoke-EspansrReinstall
  }
  $status = & git status -sb
  if ($status) { Write-Host (@($status)[0]) }
}

Invoke-GitSyncReinstall
